func TestRollupConcurrentWithWrites(t *testing.T) {
	r := New(time.Millisecond)
	var wg sync.WaitGroup
	stop := make(chan struct{})
	for g := 0; g < 4; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			at := time.Unix(0, 0)
			for i := 0; ; i++ {
				select {
				case <-stop:
					return
				default:
				}
