	if len(got) != len(want) {
		t.Fatalf("factor 1: got %d windows, want %d", len(got), len(want))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("factor 1: window %d differs: got %+v, want %+v", i, got[i], want[i])
		}
	}
